import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------- CUDA kernel source --------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

__global__ void sigmoid_kernel(const half* __restrict__ input,
                               half* __restrict__ output,
                               size_t N) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    size_t stride = blockDim.x * gridDim.x;
    for (size_t i = idx; i < N; i += stride) {
        float x = __half2float(input[i]);
        float y = 1.0f / (1.0f + expf(-x));
        output[i] = __float2half(y);
    }
}

void sigmoid_forward(at::Tensor input, at::Tensor output) {
    const size_t N = input.numel();
    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;

    sigmoid_kernel<<<blocks, threads>>>(
        input.data_ptr<at::Half>(),
        output.data_ptr<at::Half>(),
        N
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("sigmoid_forward", &sigmoid_forward, "Sigmoid forward (CUDA)");
}
'''

# -------------------- Build the extension --------------------
sigmoid_cuda = load_inline(
    name='sigmoid_cuda',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['sigmoid_forward'],
    verbose=False,
)

# -------------------- Autograd Function --------------------
class SigmoidFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input):
        output = torch.empty_like(input)
        sigmoid_cuda.sigmoid_forward(input, output)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        # Derivative of sigmoid: s * (1 - s)
        # Re‑use the forward sigmoid for efficiency
        s = SigmoidFunction.apply(grad_output)  # actually recompute sigmoid(grad_output)
        grad_input = grad_output * s * (1.0 - s)
        return grad_input

# -------------------- Model wrapper --------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Applies the custom CUDA Sigmoid to fp16 tensors.
    """
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return SigmoidFunction.apply(x)
